import { useState } from "react";
import { GameBoard } from "./components/GameBoard";
import { GameStatus } from "./components/GameStatus";
import { ScoreBoard } from "./components/ScoreBoard";
import { ResetButton } from "./components/ResetButton";
import { calculateWinner } from "./utils/gameLogic";

export type Player = "X" | "O" | null;

export interface GameState {
  board: Player[];
  currentPlayer: "X" | "O";
  winner: Player;
  winningLine: number[] | null;
  isDraw: boolean;
}

export interface Scores {
  X: number;
  O: number;
  draws: number;
}

const initialBoard = Array(9).fill(null);

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    board: initialBoard,
    currentPlayer: "X",
    winner: null,
    winningLine: null,
    isDraw: false,
  });

  const [scores, setScores] = useState<Scores>({ X: 0, O: 0, draws: 0 });

  const handleCellClick = (index: number) => {
    if (gameState.board[index] || gameState.winner) return;

    const newBoard = [...gameState.board];
    newBoard[index] = gameState.currentPlayer;

    const { winner, line } = calculateWinner(newBoard);
    const isDraw = !winner && newBoard.every((cell) => cell !== null);

    if (winner) {
      setScores((prev) => ({
        ...prev,
        [winner]: prev[winner] + 1,
      }));
    } else if (isDraw) {
      setScores((prev) => ({
        ...prev,
        draws: prev.draws + 1,
      }));
    }

    setGameState({
      board: newBoard,
      currentPlayer: gameState.currentPlayer === "X" ? "O" : "X",
      winner,
      winningLine: line,
      isDraw,
    });
  };

  const handleReset = () => {
    setGameState({
      board: initialBoard,
      currentPlayer: "X",
      winner: null,
      winningLine: null,
      isDraw: false,
    });
  };

  return (
    <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-md">
        <h1 className="text-5xl font-bold text-center mb-2 text-amber-400 tracking-tight">
          TIC TAC TOE
        </h1>
        <p className="text-slate-400 text-center mb-8 text-sm tracking-widest uppercase">
          Classic Strategy Game
        </p>

        <ScoreBoard scores={scores} />

        <GameStatus
          currentPlayer={gameState.currentPlayer}
          winner={gameState.winner}
          isDraw={gameState.isDraw}
        />

        <GameBoard
          board={gameState.board}
          winningLine={gameState.winningLine}
          onCellClick={handleCellClick}
        />

        <ResetButton onClick={handleReset} />
      </div>
    </div>
  );
}

import { Player } from "../App";
import { Cell } from "./Cell";

interface GameBoardProps {
  board: Player[];
  winningLine: number[] | null;
  onCellClick: (index: number) => void;
}

export function GameBoard({ board, winningLine, onCellClick }: GameBoardProps) {
  return (
    <div className="bg-slate-800 p-4 rounded-2xl shadow-2xl mb-6">
      <div className="grid grid-cols-3 gap-3">
        {board.map((value, index) => (
          <Cell
            key={index}
            value={value}
            index={index}
            isWinning={winningLine?.includes(index) || false}
            onClick={() => onCellClick(index)}
          />
        ))}
      </div>
    </div>
  );
}

import { Player } from "../App";
import { motion } from "framer-motion";

interface CellProps {
  value: Player;
  index: number;
  isWinning: boolean;
  onClick: () => void;
}

export function Cell({ value, index, isWinning, onClick }: CellProps) {
  return (
    <motion.button
      onClick={onClick}
      disabled={value !== null}
      className={`
        aspect-square rounded-xl text-5xl font-bold
        transition-all duration-200 ease-out
        ${value === null ? "bg-slate-700 hover:bg-slate-600 cursor-pointer" : "bg-slate-700 cursor-default"}
        ${isWinning ? "bg-amber-500 ring-4 ring-amber-300" : ""}
        ${value === "X" ? "text-cyan-400" : ""}
        ${value === "O" ? "text-rose-400" : ""}
        disabled:cursor-default
      `}
      initial={{ scale: 0.8, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      transition={{ delay: index * 0.05, duration: 0.2 }}
      whileHover={value === null ? { scale: 1.05 } : {}}
      whileTap={value === null ? { scale: 0.95 } : {}}
    >
      {value && (
        <motion.span
          initial={{ scale: 0, rotate: -180 }}
          animate={{ scale: 1, rotate: 0 }}
          transition={{ type: "spring", stiffness: 500, damping: 20 }}
          className="block"
        >
          {value}
        </motion.span>
      )}
    </motion.button>
  );
}

import { useState } from "react";
import { Calculator } from "./components/Calculator";
import { Header } from "./components/Header";
import { History } from "./components/History";

export interface Calculation {
  id: string;
  expression: string;
  result: string;
  timestamp: Date;
}

export default function App() {
  const [history, setHistory] = useState<Calculation[]>([]);

  const addToHistory = (expression: string, result: string) => {
    const newCalculation: Calculation = {
      id: Date.now().toString(),
      expression,
      result,
      timestamp: new Date(),
    };
    setHistory((prev) => [newCalculation, ...prev].slice(0, 10));
  };

  const clearHistory = () => {
    setHistory([]);
  };

  return (
    <div className="min-h-screen bg-slate-900">
      <Header />
      <main className="max-w-6xl mx-auto px-4 py-8">
        <div className="grid lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2">
            <Calculator onCalculate={addToHistory} />
          </div>
          <div className="lg:col-span-1">
            <History items={history} onClear={clearHistory} />
          </div>
        </div>
      </main>
    </div>
  );
}

import { useState } from "react";
import { CalculatorDisplay } from "./components/CalculatorDisplay";
import { CalculatorKeypad } from "./components/CalculatorKeypad";
import { History } from "./components/History";

export interface CalculationHistory {
  id: string;
  expression: string;
  result: string;
  timestamp: Date;
}

export default function App() {
  const [display, setDisplay] = useState("0");
  const [previousValue, setPreviousValue] = useState<string | null>(null);
  const [operator, setOperator] = useState<string | null>(null);
  const [waitingForOperand, setWaitingForOperand] = useState(false);
  const [history, setHistory] = useState<CalculationHistory[]>([]);

  const inputDigit = (digit: string) => {
    if (waitingForOperand) {
      setDisplay(digit);
      setWaitingForOperand(false);
    } else {
      setDisplay(display === "0" ? digit : display + digit);
    }
  };

  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplay("0.");
      setWaitingForOperand(false);
      return;
    }
    if (!display.includes(".")) {
      setDisplay(display + ".");
    }
  };

  const clear = () => {
    setDisplay("0");
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
  };

  const toggleSign = () => {
    setDisplay(String(-parseFloat(display)));
  };

  const inputPercent = () => {
    setDisplay(String(parseFloat(display) / 100));
  };

  const performOperation = (nextOperator: string) => {
    const inputValue = parseFloat(display);

    if (previousValue === null) {
      setPreviousValue(display);
    } else if (operator) {
      const currentValue = parseFloat(previousValue);
      let result: number;

      switch (operator) {
        case "+":
          result = currentValue + inputValue;
          break;
        case "-":
          result = currentValue - inputValue;
          break;
        case "×":
          result = currentValue * inputValue;
          break;
        case "÷":
          result = inputValue !== 0 ? currentValue / inputValue : 0;
          break;
        default:
          result = inputValue;
      }

      const resultString = String(parseFloat(result.toFixed(10)));
      setDisplay(resultString);
      setPreviousValue(resultString);

      if (nextOperator === "=") {
        const newHistoryItem: CalculationHistory = {
          id: Date.now().toString(),
          expression: `${currentValue} ${operator} ${inputValue}`,
          result: resultString,
          timestamp: new Date(),
        };
        setHistory((prev) => [newHistoryItem, ...prev].slice(0, 10));
      }
    }

    setWaitingForOperand(true);
    setOperator(nextOperator === "=" ? null : nextOperator);
    if (nextOperator === "=") {
      setPreviousValue(null);
    }
  };

  const handleFunction = (fn: string) => {
    switch (fn) {
      case "clear":
        clear();
        break;
      case "sign":
        toggleSign();
        break;
      case "percent":
        inputPercent();
        break;
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <h1 className="text-amber-400 text-2xl font-bold mb-6 text-center tracking-tight">
          Calculator
        </h1>
        <div className="bg-slate-800 rounded-3xl shadow-2xl overflow-hidden border border-slate-700">
          <CalculatorDisplay
            value={display}
            operator={operator}
            previousValue={previousValue}
          />
          <CalculatorKeypad
            onDigit={inputDigit}
            onDecimal={inputDecimal}
            onOperator={performOperation}
            onFunction={handleFunction}
          />
        </div>
        {history.length > 0 && <History items={history} />}
      </div>
    </div>
  );
}

import { motion } from "framer-motion";

interface CalculatorDisplayProps {
  value: string;
  operator: string | null;
  previousValue: string | null;
}

export function CalculatorDisplay({
  value,
  operator,
  previousValue,
}: CalculatorDisplayProps) {
  const formatDisplay = (val: string) => {
    const num = parseFloat(val);
    if (isNaN(num)) return val;
    if (val.length > 12) {
      return num.toExponential(6);
    }
    return val;
  };

  return (
    <div className="bg-slate-900 p-6 border-b border-slate-700">
      <div className="h-8 mb-2 text-right">
        {previousValue && operator && (
          <motion.span
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-slate-500 text-lg"
          >
            {previousValue} {operator}
          </motion.span>
        )}
      </div>
      <motion.div
        key={value}
        initial={{ opacity: 0.5, scale: 0.98 }}
        animate={{ opacity: 1, scale: 1 }}
        className="text-right text-white text-5xl font-light tracking-tight overflow-hidden"
      >
        {formatDisplay(value)}
      </motion.div>
    </div>
  );
}

import { motion } from "framer-motion";
import { Delete } from "lucide-react";

interface CalculatorKeypadProps {
  onDigit: (digit: string) => void;
  onDecimal: () => void;
  onOperator: (operator: string) => void;
  onFunction: (fn: string) => void;
}

export function CalculatorKeypad({
  onDigit,
  onDecimal,
  onOperator,
  onFunction,
}: CalculatorKeypadProps) {
  const buttons = [
    { label: "C", action: () => onFunction("clear"), type: "function" },
    { label: "±", action: () => onFunction("sign"), type: "function" },
    { label: "%", action: () => onFunction("percent"), type: "function" },
    { label: "÷", action: () => onOperator("÷"), type: "operator" },
    { label: "7", action: () => onDigit("7"), type: "number" },
    { label: "8", action: () => onDigit("8"), type: "number" },
    { label: "9", action: () => onDigit("9"), type: "number" },
    { label: "×", action: () => onOperator("×"), type: "operator" },
    { label: "4", action: () => onDigit("4"), type: "number" },
    { label: "5", action: () => onDigit("5"), type: "number" },
    { label: "6", action: () => onDigit("6"), type: "number" },
    { label: "-", action: () => onOperator("-"), type: "operator" },
    { label: "1", action: () => onDigit("1"), type: "number" },
    { label: "2", action: () => onDigit("2"), type: "number" },
    { label: "3", action: () => onDigit("3"), type: "number" },
    { label: "+", action: () => onOperator("+"), type: "operator" },
    { label: "0", action: () => onDigit("0"), type: "number", wide: true },
    { label: ".", action: () => onDecimal(), type: "number" },
    { label: "=", action: () => onOperator("="), type: "operator" },
  ];

  const getButtonStyles = (type: string) => {
    switch (type) {
      case "function":
        return "bg-slate-700 text-amber-400 hover:bg-slate-600 active:bg-slate-500";
      case "operator":
        return "bg-amber-500 text-white hover:bg-amber-400 active:bg-amber-600";
      default:
        return "bg-slate-600 text-white hover:bg-slate-500 active:bg-slate-400";
    }
  };

  return (
    <div className="grid grid-cols-4 gap-2 p-4">
      {buttons.map((button, index) => (
        <motion.button
          key={button.label}
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ delay: index * 0.02 }}
          whileTap={{ scale: 0.95 }}
          whileHover={{ scale: 1.05 }}
          onClick={button.action}
          className={`
            ${getButtonStyles(button.type)}
            ${button.wide ? "col-span-2" : ""}
            h-16 rounded-2xl text-2xl font-medium transition-colors
            flex items-center justify-center
          `}
        >
          {button.label === "C" ? <Delete className="w-6 h-6" /> : button.label}
        </motion.button>
      ))}
    </div>
  );
}

import { motion, AnimatePresence } from "framer-motion";
import { Clock } from "lucide-react";
import type { CalculationHistory } from "../App";

interface HistoryProps {
  items: CalculationHistory[];
}

export function History({ items }: HistoryProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.3 }}
      className="mt-6 bg-slate-800 rounded-2xl p-4 border border-slate-700"
    >
      <div className="flex items-center gap-2 mb-3">
        <Clock className="w-4 h-4 text-amber-400" />
        <h2 className="text-slate-400 text-sm font-medium">Recent History</h2>
      </div>
      <div className="space-y-2 max-h-48 overflow-y-auto">
        <AnimatePresence>
          {items.map((item) => (
            <motion.div
              key={item.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              className="flex justify-between items-center py-2 px-3 bg-slate-700/50 rounded-lg"
            >
              <span className="text-slate-300 text-sm">{item.expression}</span>
              <span className="text-amber-400 font-medium">= {item.result}</span>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

